-- ============================================================
-- cipherdata_malformed.sql — 服务端密文输入健壮性（畸形/异版本密文）
--
-- 背景（回归遗留问题登记第 6 项：后端遇畸形密文 double free 崩实例）：
-- 旧 V4.0.0 客户端发出的 v1.0 密文常常只有部分段非空，而 v1.0 的固定头始终
-- 带 RND/DET/OPE/SEARCH 四个长度字段。密文解析按"非空段"预留长度字段
-- （cipherdata_alloc），载荷指针却按版本声明的布局定位（CIPHERDATA_*_PTR）：
-- 两者不一致时载荷拷贝越过分配末尾，而 cipherdata_validate() 虽能识别这种
-- 不一致，却在拷贝之后才执行 —— 值被拒的同时堆已被写坏，其后任意一次 free
-- 都会让 glibc abort（实测 corrupted size vs. prev_size / free(): corrupted
-- unsorted chunks → signal 6），叠加 restart_after_crash=off 直接拖垮整个实例。
-- 同族还有一条 int32 长度求和回绕，可绕过尺寸校验拿到巨型 memcpy（段错误）。
--
-- 本用例断言：所有畸形形态一律报错且后端存活（末尾探针必须成功），
-- 同时真实旧密文（v1.0 四段齐全）仍可入库（修复前该形态可用，修复后保持）。
-- 说明：v1.0 值的字节级原样输出（cipherdata_out 的 v1.0 早退分支）已手工核对
-- 为逐字节相同；此处用 pg_column_size 断言几何（头 + 长度字段 + 载荷）正确，
-- 因为长 hex 会被 harness 归一化隐藏。
--
-- 报文故意不带 "\x" 前缀：服务端 hex 解析两种写法都接受（is_valid_hex_string →
-- strip_hex_prefix 对无前缀串原样校验），而 JDBC runner 的 replaceKeyPaths()
-- （pgjdbc TeccSqlTestRunner.java，把 SQL 里的文件路径目录改写成 --key-dir）
-- 会把以 "\" 开头的字面量当路径，整串被替换成 "<keyDir>/x0…"，带前缀的报文在
-- JDBC 侧根本到不了服务端。去掉前缀后本用例在两驱动下都验证服务端行为，
-- 因此放在 shared/（驱动无关）。
--
-- 覆盖形态 / 修复前行为：
--   ① v1.0 rnd-only（旧驱动真实输出）：越界 4*(4-非空段数)=12 字节 → 崩溃。
--      载荷取 9000 字节，使分配独立成 malloc 块，越界必定踩到下一块头部，
--      修复前稳定复现（小载荷只落在 8KB 块内空隙里静默损坏，不可靠）。
--   ② 紧凑 v2.0 的 mask 与实际长度不一致：越界 4*(popcount(mask)-非空段数) 字节。
--   ③ 尺寸求和在 int32 内回绕（rnd=det=0x7fffffff, ope=6，共 28 字节）→ 段错误。
--   ④ 负长度 → 后续段指针前移；版本头声明的长度字段多于缓冲区 → 越界读。
-- ============================================================

-- ① v1.0（0x00010000）仅 rnd 段非空：28 字节固定头 + 9000 字节载荷
--    修复后合法入库，大小 = 28 + 9000
SELECT pg_column_size(''::int4_enc) AS v1_partial_bytes;

-- ② 紧凑 v2.0 mask=0x3f（声明 6 个长度字段）但只有 eg_mul 非空
SELECT pg_column_size('000000003f00020001000000000000000000000000000000000000000000000040000000bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'::int4_enc) AS v2_mask_mismatch_bytes;

-- ③ 长度求和在 int32 回绕：头部 24 + (0x7fffffff+0x7fffffff+6 ≡ 4) = 28 字节
SELECT pg_column_size('000000000700020001000000ffffff7fffffff7f06000000deadbeef'::int4_enc) AS length_overflow_bytes;

-- ④a 负长度（v1.0 det = -16）
SELECT pg_column_size('00000000000001000100000010000000f0ffffff0000000000000000cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc'::int4_enc) AS negative_length_bytes;

-- ④b 头部截断（紧凑 v2.0 mask=0x3f 需 36 字节头，这里只有 20 字节）
SELECT pg_column_size('000000003f0002000100000000000000000000000000000000000000'::int4_enc) AS truncated_header_bytes;

-- ⑤ 对照组：合法 v1.0 四段齐全（92 字节），须仍被接受且几何正确
SELECT pg_column_size('72010000000001000100000010000000100000001000000010000000bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'::int4_enc) AS v1_allfour_bytes;

-- ⑥ 探针：后端未崩、实例未重启时才会执行
SELECT 'server survived malformed ciphertexts' AS probe;
